"""Arrays and area: a multiplication drawn as rows and columns of unit squares (a
rectangle's area). The sliders set the rows and the columns; Turn swaps them; Split by
place cuts the columns into tens and ones, the partial products."""

from vp6 import *

TENS_COLOR, ONES_COLOR = RGB(120, 170, 235), RGB(250, 190, 90)


class Form1(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Arrays and Area'
        self.Width = 680
        self.Height = 500
        self.lblRows = Label(self, Caption='Rows: 4', Left=16, Top=14, Width=90, Height=24,
                             TabIndex=1)
        self.sldRows = Slider(self, Left=106, Top=8, Width=200, Height=36, Min=1, Max=12, Value=4,
                              TabIndex=2)
        self.lblColumns = Label(self, Caption='Columns: 23', Left=326, Top=14, Width=100,
                                Height=24, TabIndex=3)
        self.sldColumns = Slider(self, Left=426, Top=8, Width=230, Height=36, Min=1, Max=30,
                                 Value=23, TickFrequency=5, TabIndex=4)
        self.cmdTurn = CommandButton(self, Caption='&Turn', Left=16, Top=52, Width=100, Height=32,
                                     TabIndex=5, ToolTipText='Swap the rows and the columns')
        self.chkSplit = CheckBox(self, Caption='&Split by place', Left=132, Top=56, Width=160,
                                 Height=26, TabIndex=6,
                                 ToolTipText='The columns cut into tens and ones: the partial products')
        self.picArray = PictureBox(self, Left=16, Top=96, Width=640, Height=300,
                                   BackColor=0xFAFFFF, TabIndex=7)
        self.lblProduct = Label(self, Caption='', Left=16, Top=408, Width=640, Height=60,
                                WordWrap=True, FontSize=16, TabIndex=8)
    # endregion

    def Form_Load(self):
        self.show()

    def sldRows_Change(self):
        self.show()

    def sldRows_Scroll(self):
        self.show()

    def sldColumns_Change(self):
        self.show()

    def sldColumns_Scroll(self):
        self.show()

    def chkSplit_Click(self):
        self.show()

    def cmdTurn_Click(self):
        rows, columns = self.sldRows.Value, self.sldColumns.Value
        if columns > self.sldRows.Max:  # (more columns than rows can have)
            self.lblProduct.Caption = f"{columns} rows won't fit: at most {self.sldRows.Max}."
            return
        self.sldRows.Value, self.sldColumns.Value = columns, rows

    def show(self):
        rows, columns = self.sldRows.Value, self.sldColumns.Value
        self.lblRows.Caption = f"Rows: {rows}"
        self.lblColumns.Caption = f"Columns: {columns}"
        text = f"{rows} × {columns} = {rows * columns}"
        tens, ones = columns // 10 * 10, columns % 10
        if self.chkSplit.Value and tens and ones:
            text += (f"   =   {rows} × {tens} + {rows} × {ones}   =   {rows * tens} + "
                     f"{rows * ones}")
        self.lblProduct.Caption = text
        self.picArray.Refresh()

    def picArray_Paint(self):
        pic = self.picArray
        rows, columns = self.sldRows.Value, self.sldColumns.Value
        size = min((pic.ScaleWidth - 24) // max(columns, 1), (pic.ScaleHeight - 24) // rows, 40)
        left, top = 12, 12
        tens = columns // 10 * 10 if self.chkSplit.Value else 0
        for row in range(rows):
            for column in range(columns):
                x, y = left + column * size, top + row * size
                gap = 6 if tens and column >= tens else 0  # (the ones apart from the tens)
                color = TENS_COLOR if column < tens else ONES_COLOR
                pic.Line(x + gap, y, x + gap + size - 2, y + size - 2, color, "BF")
                pic.Line(x + gap, y, x + gap + size - 2, y + size - 2, RGB(80, 80, 80), "B")


if __name__ == "__main__":
    run(Form1)
